    "Active Deficit": "செயலில் உள்ள பற்றாக்குறை",
    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "மத்திய கங்கை சமவெளி (யுபி, பீகார், மேற்கு வங்கம்) மற்றும் நர்மதா பள்ளத்தாக்கில் (எம்பி) தீவிரமாக உள்ளது. மேலோட்டமான நீர்நிலைகள் பருவமழைக்கு பின் +0.3மீ முதல் +0.5மீ வரை நீர்மட்ட உயர்வை காட்டுகின்றன.",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "வேர் பகுதி ஈரப்பதத்தை சமநிலைப்படுத்த கலப்பு பயிர் சாகுபடியை (மக்காச்சோளம் + பருப்பு வகைகள்) மேற்கொள்ளுங்கள்.",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "காட்டப்படும் அனைத்து மதிப்புகளும் மாதிரி மதிப்பீடு மற்றும் திட்டமிடலுக்கான உருவகப்படுத்தப்பட்ட DWLR தரவு ஆகும். எதிர்காலத்தில் நேரடி CGWB REST டெலிமெட்ரி மற்றும் IMD வானிலை கட்டமைப்பு இணைக்கப்படும்.",
    "Aquifer Rebound": "நீர்த்தேக்க மீட்சி",
    "Aquifers Depleting < 30 Days": "30 நாட்களுக்குள் வற்றும் நிலத்தடி நீர்நிலைகள்",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "டெலிமெட்ரி ஹைட்ரோஸ்டேடிக் அழுத்த பதிவுகளின் அடிப்படையில் 30 நாள் சராசரி சரிவு விகிதத்தை (மீ/மாதம்) கணக்கிடுகிறது.",
    "Clear silt from percolation tanks and farm recharge shafts.": "கசிவு நீர் குட்டைகள் மற்றும் பண்ணை ரீசார்ஜ் குழிகளில் உள்ள வண்டலை அகற்றவும்.",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "மாநில அளவிலான முன்னறிவிப்பு ஒப்பீடு, மழை எதிர்பார்ப்பு மற்றும் முன்னுரிமை விவசாய நடவடிக்கைகள்",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "வடமேற்கு சமவெளிகள் (பஞ்சாப், ஹரியானா, ராஜஸ்தான்) மற்றும் கடின பாறை பகுதிகளில் (கோலார், அனந்தபூர்) தீவிரமாக உள்ளது. உடனடி பயிர் மாற்றம் மற்றும் இரவு நேர பம்பிங் தேவை.",
