    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "ટેલિમેટ્રી હાઇડ્રોસ્ટેટિક હેડ પ્રેશર રેકોર્ડ્સના આધારે 30-દિવસના મૂવિંગ એવરેજ ઘટાડા દર (મી/મહિનો) ની ગણતરી કરે છે.",
