    "Aquifers Depleting < 30 Days": "30 ദിവസത്തിൽ താഴെ കൊണ്ട് വറ്റുന്ന അക്വിഫറുകൾ",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "ടെലിമെട്രി ഹൈഡ്രോസ്റ്റാറ്റിക് ഹെഡ് പ്രഷർ രേഖകളെ അടിസ്ഥാനമാക്കി 30 ദിവസത്തെ ശരാശരി താഴ്ച നിരക്ക് (മീ/മാസം) കണക്കാക്കുന്നു.",
    "Clear silt from percolation tanks and farm recharge shafts.": "റീചാർജ് കുളങ്ങളിൽ നിന്നും ഷാഫ്റ്റുകളിൽ നിന്നും ചെളി നീക്കം ചെയ്യുക.",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "താരതമ്യ സംസ്ഥാനതല പ്രവചനം, മഴ പ്രതീക്ഷ, മുൻഗണനാ കാർഷിക നടപടികൾ",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "വടക്ക്-പടിഞ്ഞാറൻ സമതലങ്ങളിലും (പഞ്ചാബ്, ഹരിയാന, രാജസ്ഥാൻ) ഉപദ്വീപിലെ പാറക്കെട്ടുകളുള്ള പ്രദേശങ്ങളിലും (കോലാർ, അനന്തപുർ) കേന്ദ്രീകരിച്ചിരിക്കുന്നു. ഉടനടി വിള മാറ്റവും രാത്രി പമ്പിംഗും ആവശ്യമാണ്.",
