    "Strict deficit irrigation. Run tube-wells only at night to reduce evaporation loss.": "കർശനമായ നിയന്ത്രിത നനയ്ക്കൽ രീതി പിന്തുടരുക. ബാഷ്പീകരണം കുറയ്ക്കാൻ രാത്രിയിൽ മാത്രം പമ്പുകൾ പ്രവർത്തിപ്പിക്കുക.",
