    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "ମଧ୍ୟ ଗଙ୍ଗା ଅବବାହିକା (ୟୁପି, ବିହାର, ପଶ୍ଚିମବଙ୍ଗ) ଏବଂ ନର୍ମଦା ଉପତ୍ୟକା (ଏମପି) ରେ ସକ୍ରିୟ। ମୌସୁମୀ ପରେ ଅଗଭୀର ଜଳଭଣ୍ଡାରରେ +୦.୩ ମିଟରରୁ +୦.୫ ମିଟର ଜଳସ୍ତର ସୁଧାର ଦେଖାଯାଏ।",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "ଚେର ଅଞ୍ଚଳରେ ଆର୍ଦ୍ରତା ସନ୍ତୁଳନ ରଖିବା ପାଇଁ ମିଶ୍ରିତ ଫସଲ (ମକା + ଡାଲି) ଆପଣାନ୍ତୁ।",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "ପ୍ରଦର୍ଶିତ ସମସ୍ତ ମୂଲ୍ୟ ମଡେଲ ମୂଲ୍ୟାଙ୍କନ ଏବଂ ଯୋଜନା ପାଇଁ ସିମ୍ୟୁଲେଟେଡ୍ DWLR ତଥ୍ୟ। ଭବିଷ୍ୟତରେ ଲାଇଭ୍ CGWB REST ଟେଲିମେଟ୍ରି ଏବଂ IMD ପାଣିପାଗ ଗ୍ରିଡ୍ ସଂଯୁକ୍ତ ହେବ।",
    "Aquifer Rebound": "ଜଳଭଣ୍ଡାର ସୁଧାର",
    "Aquifers Depleting < 30 Days": "୩୦ ଦିନରୁ କମ ସମୟରେ ଶୁଖିଯାଉଥିବା ଜଳଭଣ୍ଡାର",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "ଟେଲିମେଟ୍ରି ହାଇଡ୍ରୋଷ୍ଟାଟିକ୍ ଚାପ ରେକର୍ଡ ଉପରେ ଆଧାର କରି ୩୦-ଦିନର ହାରାହାରି ହ୍ରାସ ହାର (ମି/ମାସ) ଗଣନା କରେ।",
    "Clear silt from percolation tanks and farm recharge shafts.": "ପୁନର୍ଭରଣ ପୋଖରୀ ଏବଂ ଫାର୍ମ ଶାଫ୍ଟରୁ ପଙ୍କ ସଫା କରନ୍ତୁ।",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "ତୁଳନାତ୍ମକ ରାଜ୍ୟସ୍ତରୀୟ ପୂର୍ବାନୁମାନ, ବର୍ଷା ଆଶା ଏବଂ ପ୍ରାଥମିକ କୃଷି କାର୍ଯ୍ୟାନୁଷ୍ଠାନ",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "ଉତ୍ତର-ପଶ୍ଚିମ ସମତଳ ଅଞ୍ଚଳ (ପଞ୍ଜାବ, ହରିୟାଣା, ରାଜସ୍ଥାନ) ଏବଂ ପଥୁରିଆ ଅଞ୍ଚଳ (କୋଲାର, ଅନନ୍ତପୁର) ରେ କେନ୍ଦ୍ରୀଭୂତ। ତୁରନ୍ତ ଫସଲ ପରିବର୍ତ୍ତନ ଏବଂ ରାତିରେ ପମ୍ପିଂ ଆବଶ୍ୟକ।",
    "Confidence": "ବିଶ୍ୱାସନୀୟତା",
    "Crop Rotation": "ଫସଲ ପର୍ଯ୍ୟାୟ",
    "Crop Switch": "ଫସଲ ପରିବର୍ତ୍ତନ",
    "Cumulative Change": "ମୋଟ ପରିବର୍ତ୍ତନ",
    "Current Avg Depth": "ବର୍ତ୍ତମାନ ହାରାହାରି ଗଭୀରତା",
    "Current Trend": "ବର୍ତ୍ତମାନର ଧାରା",
    "Days to critical distribution": "ଗୁରୁତର ଦିନର ବଣ୍ଟନ",
    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "ଗୁରୁତର ଦିନର ଅନୁମାନ ବର୍ତ୍ତମାନର ଜଳ ହ୍ରାସ ହାର ଏବଂ ପୂର୍ବ ମୌସୁମୀ ପୁନର୍ଭରଣ ଆଧାରରେ କରାଯାଏ। ବର୍ଷା ଓ ପମ୍ପିଂ ଅନୁସାରେ ଏହା ପରିବର୍ତ୍ତିତ ହୁଏ।",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(ବର୍ତ୍ତମାନ ଗଭୀରତା - ଗୁରୁତର ସୀମା) / ଦୈନିକ ହ୍ରାସ ହାର ଭାବରେ ଅନୁମାନିତ, ଯାହା ମୌସୁମୀ ବର୍ଷା ପୁନର୍ଭରଣ ଗୁଣାଙ୍କ ଦ୍ୱାରା ସୀମିତ।",
    "Expected": "ପ୍ରତ୍ୟାଶିତ",
