    "Monsoon Infiltration Model": "ମୌସୁମୀ ପୁନର୍ଭରଣ ମଡେଲ",
    "National Network Breakdown by Days Remaining": "ବାକି ଥିବା ଦିନ ଅନୁସାରେ ଜାତୀୟ ନେଟୱାର୍କ ବିବରଣୀ",
    "Network Risk Balance: Stressed vs Resilient Aquifers": "ନେଟୱାର୍କ ବିପଦ ସନ୍ତୁଳନ: ସଙ୍କଟଗ୍ରସ୍ତ ବନାମ ସ୍ଥିର ଜଳଭଣ୍ଡାର",
    "Observation Well": "ପର୍ଯ୍ୟବେକ୍ଷଣ କୂଅ",
