    "Observation Wells Evaluated": "ମୂଲ୍ୟାଙ୍କିତ ପର୍ଯ୍ୟବେକ୍ଷଣ କୂଅ",
    "Observation wells with robust storage buffer, positive infiltration, and safe multi-horizon margins": "ମଜବୁତ ସଂରକ୍ଷଣ ବଫର, ସକାରାତ୍ମକ ପୁନର୍ଭରଣ ଏବଂ ସୁରକ୍ଷିତ ସୀମା ବିଶିଷ୍ଟ ପର୍ଯ୍ୟବେକ୍ଷଣ କୂଅ",
