    "Ranked observation wells facing rapid depletion and imminent critical threshold arrival": "ଦ୍ରୁତ ହ୍ରାସ ଏବଂ ଖୁବ୍ ଶୀଘ୍ର ଗୁରୁତର ସୀମା ଛୁଇଁବାକୁ ଥିବା ପର୍ଯ୍ୟବେକ୍ଷଣ କୂଅ",
    "Recharge Maintenance": "ପୁନର୍ଭରଣ ରକ୍ଷଣାବେକ୍ଷଣ",
    "Recharging & Stable Zones": "ପୁନର୍ଭରଣ ଏବଂ ସ୍ଥିର ଅଞ୍ଚଳ",
    "Regional Groundwater Outlook (90-Day Projections)": "ଆଞ୍ଚଳିକ ଭୂତଳ ଜଳ ଦୃଶ୍ୟପଟ୍ଟ (୯୦ ଦିନର ପୂର୍ବାନୁମାନ)",
    "Rising": "ବୃଦ୍ଧି ପାଉଛି",
    "Safe (90+ Days)": "ସୁରକ୍ଷିତ (୯୦+ ଦିନ)",
    "Severity Brackets": "ଗମ୍ଭୀରତା ଶ୍ରେଣୀ",
    "Soil Infiltration": "ମାଟିରେ ଜଳ ଶୋଷଣ",
    "Stable": "ସ୍ଥିର",
    "State": "ରାଜ୍ୟ",
    "State Aggregate": "ରାଜ୍ୟ ମୋଟ",
    "State Scope": "ରାଜ୍ୟ ପରିସର",
    "Station Scope": "ଷ୍ଟେସନ ପରିସର",
    "Stay alert for sudden pumping anomalies during peak flowering.": "ଫୁଲ ଫୁଟିବା ସମୟରେ ହଠାତ୍ ଅତ୍ୟଧିକ ପମ୍ପିଂ ଉପରେ ସତର୍କ ରୁହନ୍ତୁ।",
    "Strict deficit irrigation. Run tube-wells only at night to reduce evaporation loss.": "ନିୟନ୍ତ୍ରିତ ଜଳସେଚନ କରନ୍ତୁ। ବାଷ୍ପୀଭବନ ରୋକିବା ପାଇଁ କେବଳ ରାତିରେ ନଳକୂପ ଚଲାନ୍ତୁ।",
    "Telemetry Tracking": "ଟେଲିମେଟ୍ରି ଟ୍ରାକିଂ",
    "Test soil moisture before turning on pumps; avoid over-saturation.": "ପମ୍ପ ଚଳାଇବା ପୂର୍ବରୁ ମାଟିର ଆର୍ଦ୍ରତା ଯାଞ୍ଚ କରନ୍ତୁ; ଅତ୍ୟଧିକ ଜଳସେଚନରୁ ଦୂରେଇ ରୁହନ୍ତୁ।",
    "The groundwater forecasts combine DWLR time-series drawdown velocity, seasonal precipitation forecasts, and soil-aquifer infiltration parameters to estimate future water table depths and days-to-critical thresholds.": "ଭୂତଳ ଜଳ ପୂର୍ବାନୁମାନ ଭବିଷ୍ୟତର ଜଳସ୍ତର ଗଭୀରତା ଏବଂ ଗୁରୁତର ଦିନ ଆକଳନ କରିବାକୁ DWLR ହ୍ରାସ ବେଗ, ମୌସୁମୀ ବର୍ଷା ପୂର୍ବାନୁମାନ ଏବଂ ମାଟି-ଜଳଭଣ୍ଡାର ପୁନର୍ଭରଣ ପାରାମିଟରକୁ ଯୋଡିଥାଏ।",
    "Track Station on Map": "ମାନଚିତ୍ରରେ ଷ୍ଟେସନ୍ ଟ୍ରାକ୍ କରନ୍ତୁ",
